require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$user=require_login();$workspace=require_permission('build_dashboard');$dashboardId=filter_var($_POST['dashboard_id']??null,FILTER_VALIDATE_INT);$datasetId=filter_var($_POST['dataset_id']??null,FILTER_VALIDATE_INT);$title=trim((string)($_POST['title']??''));$question=trim((string)($_POST['question']??''));$type=(string)($_POST['widget_type']??'metric');$allowed=plan_limits($workspace)['builder']?['metric','line','bar','donut','table']:['metric','line','bar','table'];$st=$GLOBALS['pdo']->prepare('SELECT id FROM dashboards WHERE id=? AND workspace_id=?');$st->execute([$dashboardId,$workspace['id']]);if(!$st->fetchColumn()){$error='Dashboard tidak ditemukan.';}elseif(!in_array($type,$allowed,true)){$error='Jenis widget tidak tersedia di paket ini.';}elseif(mb_strlen($title,'UTF-8')<2||mb_strlen($title,'UTF-8')>180||$question===''||mb_strlen($question,'UTF-8')>1500){$error='Judul dan pertanyaan widget tidak valid.';}else{$st=$GLOBALS['pdo']->prepare('SELECT id FROM datasets WHERE id=? AND workspace_id=?');$st->execute([$datasetId,$workspace['id']]);if(!$st->fetchColumn())$error='Dataset tidak ditemukan pada workspace aktif.';else{$st=$GLOBALS['pdo']->prepare('SELECT COUNT(*) FROM dashboard_widgets w JOIN dashboards d ON d.id=w.dashboard_id WHERE d.workspace_id=?');$st->execute([$workspace['id']]);$count=(int)$st->fetchColumn();$max=plan_limits($workspace)['builder']?100:3;if($count>=$max)$error='Batas widget paket ini tercapai.';else{$st=$GLOBALS['pdo']->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM dashboard_widgets WHERE dashboard_id=?');$st->execute([$dashboardId]);$sort=(int)$st->fetchColumn();$GLOBALS['pdo']->prepare('INSERT INTO dashboard_widgets(dashboard_id,dataset_id,widget_type,title,metric_key,config_json,sort_order) VALUES(?,?,?,?,?,?,?)')->execute([$dashboardId,$datasetId,$type,$title,null,json_encode(['question'=>$question],JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$sort]);audit_log('dashboard.widget_added','dashboard',(int)$dashboardId,['type'=>$type]);flash('success','Widget ditambahkan.');redirect('dashboards/view.php?id='.$dashboardId);}}}flash('error',$error);redirect('dashboards/view.php?id='.(int)$dashboardId);
